{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policy is attached to a group or role",
      "resource": "aws_iam_user_policy_attachment.privesc15-PassExistingRoleToNewLambdaThenInvoke-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users instead of groups or roles can lead to privilege escalation and is considered a security best practice violation."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc15-PassExistingRoleToNewLambdaThenInvoke-group" {
  name = "privesc15-PassExistingRoleToNewLambdaThenInvoke-group"
}

resource "aws_iam_group_membership" "privesc15-PassExistingRoleToNewLambdaThenInvoke-membership" {
  name  = "privesc15-PassExistingRoleToNewLambdaThenInvoke-membership"
  users = [aws_iam_user.privesc15-PassExistingRoleToNewLambdaThenInvoke-user.name]
  group = aws_iam_group.privesc15-PassExistingRoleToNewLambdaThenInvoke-group.name
}

resource "aws_iam_group_policy_attachment" "privesc15-PassExistingRoleToNewLambdaThenInvoke-group-attach-policy" {
  group      = aws_iam_group.privesc15-PassExistingRoleToNewLambdaThenInvoke-group.name
  policy_arn = aws_iam_policy.privesc15-PassExistingRoleToNewLambdaThenInvoke.arn
}",
  "fix_summary": "Replaced the user policy attachment with a group policy attachment, creating a new group and adding the user to it, to follow IAM best practices."
}
